-- ============================================================
-- Seed Mathematics Materials - PART 1
-- ============================================================
DO $$
DECLARE
  unilag_id UUID;
  math_dept_id UUID;
  v_uploader_id UUID;
BEGIN
  SELECT id INTO unilag_id FROM public.universities WHERE short_name = 'UNILAG';
  IF unilag_id IS NULL THEN RETURN; END IF;
  
  SELECT id INTO math_dept_id FROM public.departments WHERE university_id = unilag_id AND name = 'Mathematics';
  IF math_dept_id IS NULL THEN RETURN; END IF;
  
  SELECT user_id INTO v_uploader_id FROM public.user_roles WHERE role = 'admin' LIMIT 1;
  IF v_uploader_id IS NULL THEN
    SELECT id INTO v_uploader_id FROM public.profiles LIMIT 1;
  END IF;
  IF v_uploader_id IS NULL THEN RETURN; END IF;
  
  -- Define Seeding Helper Function
  CREATE OR REPLACE FUNCTION public.seed_material_helper(
    p_title TEXT,
    p_desc TEXT,
    p_type TEXT,
    p_url TEXT,
    p_course_code TEXT,
    p_dept_id UUID,
    p_uploader_id UUID
  ) RETURNS VOID AS $inner$
  BEGIN
    INSERT INTO public.materials (title, description, type, file_url, course_id, uploaded_by, status)
    SELECT 
      p_title,
      p_desc,
      p_type::public.material_type,
      p_url,
      c.id,
      p_uploader_id,
      'approved'::public.material_status
    FROM public.courses c
    WHERE c.code = p_course_code 
      AND c.department_id = p_dept_id
      AND NOT EXISTS (
        SELECT 1 FROM public.materials m 
        WHERE m.file_url = p_url
      );
  END;
  $inner$ LANGUAGE plpgsql;
  
